/**
 * 判断两个对象是否不同，不同则返回true，相同则返回false
 *
 *
 * 比较是baseObj为基准的，如果refObj中有baseObj中没有的属性，则不会被比较
 *
 * @param baseObj
 * @param refObj
 * @param isRecursion  当isDiff被递归调用时置为true
 * @returns {Boolean}
 */
declare function isDiff(baseObj: Record<string, any> | [], refObj: Record<string, any> | []): boolean;

export { isDiff };
